const items = $input.all();

// Маппинг реальных колонок по номерам __EMPTY
const COLS = {
  name:        'Период: 27.04.2026 \u2013 03.05.2026', // название товара
  category1:   '__EMPTY',
  sku:         '__EMPTY_7',   // Артикул
  ozon_id:     '__EMPTY_6',   // SKU Ozon
  abc_sum:     '__EMPTY_8',   // ABC по сумме
  revenue:     '__EMPTY_10',  // Заказано на сумму
  rev_delta:   '__EMPTY_11',  // Динамика выручки
  position:    '__EMPTY_14',  // Позиция в поиске
  shows:       '__EMPTY_16',  // Показы всего
  show_delta:  '__EMPTY_17',  // Динамика показов
  conv_order:  '__EMPTY_18',  // Конверсия из показа в заказ
  shows_search:'__EMPTY_20',  // Показы в поиске
  cart_from_search: '__EMPTY_22', // Конверсия поиск→корзина
  card_visits: '__EMPTY_28',  // Посещения карточки
  card_delta:  '__EMPTY_29',  // Динамика посещений
  cart_from_card: '__EMPTY_30', // Конверсия карточка→корзина
  cart_total:  '__EMPTY_34',  // Конверсия в корзину общая
  ordered:     '__EMPTY_40',  // Заказано товаров (шт)
  ord_delta:   '__EMPTY_41',  // Динамика заказов
  buyout_rate: '__EMPTY_44',  // Конверсия из заказа в выкуп
  cancelled:   '__EMPTY_48',  // Отменено товаров
  returned:    '__EMPTY_52',  // Возвращено товаров
  avg_price:   '__EMPTY_56',  // Средняя цена
  discount:    '__EMPTY_58',  // Скидка
  price_index: '__EMPTY_60',  // Индекс цен
  drr:         '__EMPTY_62',  // Общая ДРР
  days_no_stock: '__EMPTY_65',// Дней без остатка
  stock:       '__EMPTY_66',  // Остаток на конец периода
  ozon_rec:    '__EMPTY_67',  // Рекомендация Ozon
  to_supply:   '__EMPTY_68',  // Сколько поставить
  reviews:     '__EMPTY_69',  // Отзывы
  rating:      '__EMPTY_70',  // Рейтинг
};

function num(v) {
  if (v === '–' || v === null || v === undefined || v === '') return null;
  const n = Number(v);
  return isNaN(n) ? null : n;
}

// Убираем служебные строки (заголовки, описания, итого)
const SKIP_NAMES = ['Товар:', 'Категория:', 'Цена:', 'Схема работы:', 'Признак товара:',
  'Платформа:', 'Продавец:', 'Товары', 'Итого и среднее'];

const rows = items.map(i => i.json);
const products = [];

for (const r of rows) {
  const name = r[COLS.name];
  if (!name || SKIP_NAMES.some(s => String(name).startsWith(s))) continue;

  const revenue = num(r[COLS.revenue]);
  if (!revenue || revenue === 0) continue; // пропускаем нулевые товары

  const revDelta    = num(r[COLS.rev_delta]);   // дробное, напр. -0.39 = -39%
  const ordDelta    = num(r[COLS.ord_delta]);
  const ordered     = num(r[COLS.ordered]) ?? 0;
  const cancelled   = num(r[COLS.cancelled]) ?? 0;
  const returned    = num(r[COLS.returned]) ?? 0;
  const stock       = num(r[COLS.stock]);
  const drr         = num(r[COLS.drr]);
  const buyoutRate  = num(r[COLS.buyout_rate]);
  const cardVisits  = num(r[COLS.card_visits]) ?? 0;
  const cartFromCard= num(r[COLS.cart_from_card]);
  const priceIndex  = r[COLS.price_index];
  const ozonRec     = r[COLS.ozon_rec] ?? '';
  const toSupply    = num(r[COLS.to_supply]);
  const daysNoStock = r[COLS.days_no_stock] ?? '';

  // Парсим "дней без остатка": "22 из 28" → 22
  const daysNoStockNum = parseInt(String(daysNoStock).split(' ')[0]) || 0;

  // Конверсия карточка→корзина в % (уже дробное 0.12 = 12%)
  const cartConv = cartFromCard !== null ? cartFromCard * 100 : null;

  // returnRate и cancelRate от заказов
  const returnRate = ordered > 0 ? (returned / ordered) * 100 : 0;
  const cancelRate = ordered > 0 ? (cancelled / ordered) * 100 : 0;

  products.push({
    sku:          String(r[COLS.sku] ?? ''),
    name:         String(name).substring(0, 80),
    revenue,
    revDeltaPct:  revDelta !== null ? Math.round(revDelta * 100) : null,
    ordDeltaPct:  ordDelta !== null ? Math.round(ordDelta * 100) : null,
    ordered,
    cancelRate:   Math.round(cancelRate),
    returnRate:   Math.round(returnRate),
    stock:        stock !== null ? stock : '?',
    daysNoStock:  daysNoStockNum,
    cartConvPct:  cartConv !== null ? Math.round(cartConv * 10) / 10 : null,
    drr:          drr !== null ? Math.round(drr * 100) : 0,
    buyoutRate:   buyoutRate !== null ? Math.round(buyoutRate * 100) : null,
    priceIndex:   priceIndex ?? '–',
    ozonRec:      String(ozonRec),
    toSupply:     toSupply ?? 0,
    abc:          r[COLS.abc_sum] ?? '–',
  });
}

return [{ json: { products, total: products.length } }];

// Проверяем тип входящего сообщения
// Поддерживаем: документ (CSV/Excel), текст с данными или команду /analyze
const msg = $input.first().json.message ?? {};

const hasDocument = !!msg.document;
const hasText = !!msg.text;
const chatId = msg.chat?.id ?? msg.from?.id;

if (!hasDocument && !hasText) {
  return [{ json: { skip: true, chatId, reason: 'no_content' } }];
}

return [{
  json: {
    skip: false,
    chatId,
    hasDocument,
    hasText,
    text: msg.text ?? '',
    fileId: msg.document?.file_id ?? null,
    fileName: msg.document?.file_name ?? null,
    mimeType: msg.document?.mime_type ?? null
  }
}];

// Парсинг текстовых данных из Telegram (если менеджер вставил текст/JSON вручную)
const raw = $input.first().json.text ?? '';

let rows = [];

// Пробуем JSON
try {
  const parsed = JSON.parse(raw);
  rows = Array.isArray(parsed) ? parsed : [parsed];
} catch(e) {
  // Пробуем CSV (разделители: запятая или точка с запятой)
  const lines = raw.trim().split('\n').filter(Boolean);
  if (lines.length >= 2) {
    const sep = lines[0].includes(';') ? ';' : ',';
    const headers = lines[0].split(sep).map(h => h.trim().replace(/^"|"$/g, ''));
    rows = lines.slice(1).map(line => {
      const vals = line.split(sep).map(v => v.trim().replace(/^"|"$/g, ''));
      const obj = {};
      headers.forEach((h, i) => { obj[h] = isNaN(vals[i]) ? vals[i] : Number(vals[i]); });
      return obj;
    });
  }
}

if (rows.length === 0) {
  return [{ json: { error: 'Не удалось распарсить данные', raw } }];
}

return rows.map(r => ({ json: r }));

// Парсинг ответа Claude
const raw = $input.first().json;
const text = raw.output ?? raw.content?.[0]?.text ?? '{"tasks":[]}';

let parsed;
try {
  const clean = text.replace(/```json|```/g, '').trim();
  parsed = JSON.parse(clean);
} catch(e) {
  parsed = { tasks: [], error: 'parse failed', raw: text };
}

const tasks = parsed.tasks ?? [];

// Сортировка: high → medium → low
const order = { high: 0, medium: 1, low: 2 };
tasks.sort((a, b) => (order[a.priority] ?? 2) - (order[b.priority] ?? 2));

// Форматируем текст для Telegram
const priorityEmoji = { high: '🔴', medium: '🟡', low: '🟢' };
const categoryLabel = {
  restock:   '📦 Допоставка',
  price:     '💰 Цена / скидка',
  card:      '🖼 Карточка',
  ads_up:    '📈 Усилить рекламу',
  ads_down:  '📉 Снизить рекламу',
  returns:   '↩️ Возвраты',
  scale:     '🚀 Масштабирование',
  freeze:    '❄️ Заморозить закуп'
};

const lines = tasks.map(t =>
  `${priorityEmoji[t.priority] ?? '⚪'} *${t.name}* \`[${t.sku}]\`\n` +
  `${categoryLabel[t.category] ?? t.category}\n` +
  `✅ ${t.action}\n` +
  `💬 ${t.reason}\n` +
  `⏰ ${t.deadline}`
).join('\n\n─────────────\n\n');

const date = new Date().toLocaleDateString('ru-RU', { day: '2-digit', month: '2-digit', year: 'numeric' });
const highCount = tasks.filter(t => t.priority === 'high').length;
const header = `📊 *Задачи по Ozon — ${date}*\n🔴 Срочных: ${highCount} | Всего: ${tasks.length}\n`;

const telegramText = tasks.length > 0
  ? header + '\n' + lines
  : `📊 *Задачи по Ozon — ${date}*\n\n✅ Нет срочных задач — все показатели в норме`;

return [{
  json: {
    tasks,
    telegramText,
    totalTasks: tasks.length,
    highCount
  }
}];
